# Reproducible repair, applied atomically after all assets are prepared.
from pathlib import Path
import base64,zlib,json,subprocess,re,hashlib,urllib.request
BASE='affce914395b500f579ad354a179816bd1707f44'
# Existing embedded artwork and music are preserved byte-for-byte.
for file in ['index.html','timeline/index.html']:
 old=subprocess.check_output(['git','show',BASE+':'+file]).decode()
 for mime,data in re.findall(r'data:(image/(?:png|jpeg|webp|svg\+xml)|audio/mpeg);base64,([A-Za-z0-9+/=\r\n]+)',old):
  raw=base64.b64decode(data);ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp','image/svg+xml':'svg','audio/mpeg':'mp3'}[mime]
  p=Path('assets/extracted')/(hashlib.sha256(raw).hexdigest()[:20]+'.'+ext);p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
vendors=[{'name': 'maplibre-gl-4.7.1.js', 'sha256': 'be9633c4d870e26fb37f1cfe5c5a77181667114003ea16207ac7850d8da8add1', 'url': 'https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.js'}, {'name': 'maplibre-gl-4.7.1.css', 'sha256': '576b085fdd9487a65a19215328c1e086c07ce5bf6da09b666b3806d3d008dae9', 'url': 'https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.css'}, {'name': 'maplibre-gl-dates.js', 'sha256': '2428d4bb4659d3eed14cd0db2fe20b1e3fb30aed9e538dca24e68dc17df811f3', 'url': 'https://unpkg.com/@openhistoricalmap/maplibre-gl-dates@latest'}, {'name': 'historical-map-style.json', 'sha256': 'f6a046bcea38b2be52ef036f348364712723ec430bad5ea5a34957695c44a5fc', 'url': 'https://unpkg.com/@openhistoricalmap/map-styles@latest/dist/historical/historical.json'}]
for v in vendors:
 raw=urllib.request.urlopen(v['url'],timeout=30).read()
 assert hashlib.sha256(raw).hexdigest()==v['sha256'],'Vendor changed: '+v['name']
 p=Path('maps/vendor')/v['name'];p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
files=json.loads(zlib.decompress(base64.b64decode('')))
for name,record in files.items():
 p=Path(name)
 if 'new' in record:raw=record['new'].encode()
 else:
  old=p.read_bytes();assert hashlib.sha256(old).hexdigest()==record['old_sha256'],'Source changed: '+name
  lines=old.decode().splitlines(keepends=True)
  for a,b,new in reversed(record['edits']):lines[a:b]=new
  raw=''.join(lines).encode();assert hashlib.sha256(raw).hexdigest()==record['new_sha256'],'Repair hash mismatch: '+name
 p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)

subprocess.run(['python','scripts/verify_repair_v64.py'],check=True)
print('Repair prepared and verified:',len(files),'text files; original art/audio extracted unchanged.')
